import type { Decorator } from "@storybook/react-vite";
import { IntlProvider } from "react-intl";

// The compiled messages are only generated by `intl:compile`. Stories render with empty messages, so every component
// falls back to its `defaultMessage` and missing-message errors are silenced.
export const IntlProviderDecorator: Decorator = (Story) => (
    <IntlProvider
        locale="en"
        defaultLocale="en"
        messages={{}}
        onError={() => {
            // noop
        }}
    >
        <Story />
    </IntlProvider>
);
